from pathlib import Path
import subprocess,os,signal
repo=Path('/Users/steventran/jobpipe')
base='3fb4d24d11ee6f7f407c54e9265dcb490ee9024e'
def git(*args):return subprocess.run(['git',*args],cwd=repo,text=True,capture_output=True,check=True).stdout
if git('rev-parse','HEAD').strip()!=base or git('rev-parse','origin/main').strip()!=base:raise SystemExit('AUTHORITY_CHANGED')
for name in ('utils/csv_apply.py','tests/test_csv_apply.py'):
 print('TARGET',name,git('status','--short','--',name).strip(),flush=True)
source=(repo/'utils/csv_apply.py').read_text()
tests=(repo/'tests/test_csv_apply.py').read_text()
if 'if status == "registration uncertain":' not in source or 'test_uncertain_registration_cannot_be_loaded_even_with_explicit_status' not in tests:raise SystemExit('PREVIOUS_FIX_NOT_PRESENT')
def check(args,timeout):
 p=subprocess.Popen([str(repo/'.venv/bin/python'),'-m','pytest','-q','--maxfail=1','--tb=short']+args,cwd=repo,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,start_new_session=True)
 try:o,e=p.communicate(timeout=timeout)
 except subprocess.TimeoutExpired:
  os.killpg(p.pid,signal.SIGTERM)
  try:o,e=p.communicate(timeout=8)
  except subprocess.TimeoutExpired:os.killpg(p.pid,signal.SIGKILL);o,e=p.communicate()
  print('TIMEOUT',args,o[-3000:],e[-1000:],flush=True);raise SystemExit(124)
 print('RESULT',args,p.returncode,o[-4500:],e[-900:],flush=True)
 return p.returncode
if check(['tests/test_csv_apply.py','tests/test_jobctl.py'],135):raise SystemExit('CSV_GATE_FAIL')
# Target prior failed stage explicitly; do not hide an unrelated browser failure.
if check(['tests/test_workday_adapter.py'],260):raise SystemExit('WORKDAY_GATE_FAIL')
# Run no broad suite here: four shards were validated at baseline; this diff only touches CSV admission.
subprocess.run(['git','add','--','utils/csv_apply.py','tests/test_csv_apply.py'],cwd=repo,check=True)
subprocess.run(['git','commit','-m','fix: exclude uncertain registration from CSV queue even with explicit statuses'],cwd=repo,check=True)
subprocess.run(['git','push','origin','main'],cwd=repo,check=True,timeout=90)
print('VERIFIED_PUSH',git('rev-parse','HEAD').strip(),flush=True)
